package com.franco.desco.adapter.out.sqlserver.salesoperation;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.salesoperation.*;import com.franco.desco.application.salesoperation.port.out.SalesOperationPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.salesoperation.SalesOperationModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class SalesOperationSqlServerAdapter implements SalesOperationPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall list,get,create,update,zones,start,close,cancel;public SalesOperationSqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;list=f.callWithResultSets("comercial","PA_OperativoVenta_Sel_Listado","items");get=f.callWithResultSets("comercial","PA_OperativoVenta_Sel_DetalleCompleto","header","zones","participants","deliveries","incidents");create=f.call("comercial","PA_OperativoVenta_Ins_Registro");update=f.call("comercial","PA_OperativoVenta_Upd_Registro");zones=f.call("comercial","PA_OperativoVenta_Upd_Zonas");start=f.call("comercial","PA_OperativoVenta_Upd_IniciarRecepcion");close=f.call("comercial","PA_OperativoVenta_Upd_Cerrar");cancel=f.call("comercial","PA_OperativoVenta_Upd_Cancelar");}
 public PersistenceResult<PageResult<SalesOperationModels.Summary>>list(SalesOperationCommands.ListOperations c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var out=e.executeJson(list,pf.forQuery(i,m,map("filtros",map("campaniaVentaId",f==null?null:f.campaniaVentaId(),"estadoProceso",f==null?null:f.estadoProceso()),"paginacion",map("pagina",pg.pagina(),"tamano",pg.tamanio()))));return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::summary,"No se pudieron consultar los operativos.");}
 public PersistenceResult<SalesOperationModels.Detail>get(SalesOperationCommands.Get c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(get,pf.forQuery(i,m,Map.of("operativo",Map.of("operativoVentaId",c.operativoVentaId()))));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar el operativo."));var h=one(out,"header");if(h==null)return PersistenceResult.error("El operativo seleccionado no está disponible.");return PersistenceResult.ok(PaAdapterSupport.message(out,"Operativo consultado correctamente."),new SalesOperationModels.Detail(header(h),rows(out,"zones").stream().map(this::zone).toList(),rows(out,"participants").stream().map(this::participant).toList(),rows(out,"deliveries").stream().map(this::delivery).toList(),rows(out,"incidents").stream().map(this::incident).toList()));}
 public PersistenceResult<Long>create(SalesOperationCommands.Create c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(create,pf.forWrite(i,m,c,Map.of("operativo",map("campaniaVentaId",c.campaniaVentaId(),"codigo",c.codigo(),"fechaInicioProgramada",c.fechaInicioProgramada(),"fechaFinProgramada",c.fechaFinProgramada(),"observacion",c.observacion()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nOperativoVentaId"),"No se pudo crear el operativo.");}public PersistenceResult<Void>update(SalesOperationCommands.Update c,SessionIdentity i,RequestMetadata m){return mut(update,i,m,c,map("operativoVentaId",c.operativoVentaId(),"fechaInicioProgramada",c.fechaInicioProgramada(),"fechaFinProgramada",c.fechaFinProgramada(),"observacion",c.observacion()),"No se pudo actualizar el operativo.");}
 public PersistenceResult<Void>setZones(SalesOperationCommands.SetZones c,SessionIdentity i,RequestMetadata m){var payload=map("operativo",Map.of("operativoVentaId",c.operativoVentaId()),"zonas",c.zonas()==null?List.of():c.zonas().stream().map(z->Map.of("zonaProductivaId",z)).toList());return PaAdapterSupport.result(e.executeJson(zones,pf.forWrite(i,m,c,payload)),null,"No se pudieron actualizar las zonas.");}public PersistenceResult<Void>startReception(SalesOperationCommands.Transition c,SessionIdentity i,RequestMetadata m){return mut(start,i,m,c,map("operativoVentaId",c.operativoVentaId(),"motivo",c.motivo()),"No se pudo iniciar la recepción.");}public PersistenceResult<Void>close(SalesOperationCommands.Transition c,SessionIdentity i,RequestMetadata m){return mut(close,i,m,c,map("operativoVentaId",c.operativoVentaId(),"motivo",c.motivo()),"No se pudo cerrar el operativo.");}public PersistenceResult<Void>cancel(SalesOperationCommands.Transition c,SessionIdentity i,RequestMetadata m){return mut(cancel,i,m,c,map("operativoVentaId",c.operativoVentaId(),"motivo",c.motivo()),"No se pudo cancelar el operativo.");}
 private PersistenceResult<Void>mut(SimpleJdbcCall call,SessionIdentity i,RequestMetadata m,Object body,Map<String,Object>v,String f){return PaAdapterSupport.result(e.executeJson(call,pf.forWrite(i,m,body,Map.of("operativo",v))),null,f);}private SalesOperationModels.Summary summary(Map<String,Object>r){return new SalesOperationModels.Summary(SqlValues.longValue(r,"operativoVentaId"),SqlValues.longValue(r,"campaniaVentaId"),SqlValues.string(r,"campania"),SqlValues.string(r,"codigo"),SqlValues.instant(r,"fechaInicioProgramada"),SqlValues.instant(r,"fechaFinProgramada"),SqlValues.instant(r,"fechaInicioReal"),SqlValues.instant(r,"fechaFinReal"),SqlValues.intValue(r,"cantidadJabasRecibidas"),SqlValues.longValue(r,"jabasAsignadas"),SqlValues.longValue(r,"jabasDevueltas"),SqlValues.longValue(r,"jabasDisponibles"),SqlValues.longValue(r,"jabasPendientes"),SqlValues.decimal(r,"kilosRecibidos"),SqlValues.decimal(r,"kilosAceptados"),SqlValues.decimal(r,"kilosRechazados"),SqlValues.string(r,"estadoProceso"),SqlValues.string(r,"observacion"),SqlValues.longValue(r,"participantes"),SqlValues.longValue(r,"entregas"),SqlValues.longValue(r,"incidenciasPendientes"));}private SalesOperationModels.Header header(Map<String,Object>r){return new SalesOperationModels.Header(SqlValues.longValue(r,"operativoVentaId"),SqlValues.string(r,"codigo"),SqlValues.longValue(r,"campaniaVentaId"),SqlValues.string(r,"campania"),SqlValues.instant(r,"fechaInicioProgramada"),SqlValues.instant(r,"fechaFinProgramada"),SqlValues.instant(r,"fechaInicioReal"),SqlValues.instant(r,"fechaFinReal"),SqlValues.string(r,"estadoProceso"),SqlValues.string(r,"observacion"),SqlValues.intValue(r,"jabasRecibidas"),SqlValues.intValue(r,"jabasAsignadas"),SqlValues.intValue(r,"jabasDevueltas"),SqlValues.intValue(r,"jabasPendientes"),SqlValues.intValue(r,"jabasDisponibles"));}private SalesOperationModels.Zone zone(Map<String,Object>r){return new SalesOperationModels.Zone(SqlValues.longValue(r,"zonaProductivaId"),SqlValues.string(r,"codigo"),SqlValues.string(r,"nombre"));}private SalesOperationModels.Participant participant(Map<String,Object>r){return new SalesOperationModels.Participant(SqlValues.longValue(r,"operativoSocioId"),SqlValues.string(r,"estadoParticipacion"),SqlValues.longValue(r,"participacionId"),SqlValues.string(r,"numeroDocumento"),SqlValues.string(r,"socioNombre"));}private SalesOperationModels.Delivery delivery(Map<String,Object>r){return new SalesOperationModels.Delivery(SqlValues.longValue(r,"entregaSocioId"),SqlValues.string(r,"codigoLote"),SqlValues.instant(r,"fechaHora"),SqlValues.decimal(r,"pesoAceptadoKg"),SqlValues.string(r,"estadoControlCalidad"),SqlValues.string(r,"estadoProceso"));}private SalesOperationModels.Incident incident(Map<String,Object>r){return new SalesOperationModels.Incident(SqlValues.longValue(r,"incidenciaId"),SqlValues.string(r,"tipoIncidencia"),SqlValues.string(r,"severidad"),SqlValues.string(r,"descripcion"),SqlValues.string(r,"estadoIncidencia"));}private List<Map<String,Object>>rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private Map<String,Object>one(Map<String,Object>o,String k){return new PaResultSets(o).one(k).orElse(null);}private static Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}}
